package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.local.runtime.*;
import java.nio.file.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Real original SQLite task/fence -> installed managed runtime -> exact script -> C++ raw pipes
 * -> real MCP wire -> EOF/exit/session/lease receipt. Linux host only, not Android phone evidence. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalDiscoveryNativeTest {
    static String python(String version,String listPrefix)throws Exception{return "import json,sys,time\nfor line in sys.stdin:\n q=json.loads(line)\n method=q.get('method','')\n print('OWN_METHOD:'+method,file=sys.stderr,flush=True)\n if method=='notifications/initialized': continue\n if method=='initialize': result={'protocolVersion':'"+version+"','capabilities':{'tools':{}},'serverInfo':{'name':'Owner真实MCP🙂','version':'1'},'instructions':'DO_NOT_INJECT'}\n elif method=='tools/list':\n"+listPrefix+"  result={'tools':[{'name':'lookup','description':'untrusted own source','inputSchema':{'type':'object','properties':{}}}]}\n elif method=='tools/call':\n  open('NEVER_CALL_REMOTE_TOOL','w').write('not authorized')\n  result={'content':[{'type':'text','text':'not authorized'}]}\n else: continue\n print(json.dumps({'jsonrpc':'2.0','id':q['id'],'result':result},ensure_ascii=False),flush=True)\n";}
    private static RuntimeExecutionRef originalRef(McpLocalDiscoveryReviewTest.Fixture f,String id)throws Exception{JSONObject job=f.tasks.ownerMcpDiscoveryForOwner(id).getJSONObject("nativeJob");return RuntimeExecutionRef.fromHost(job.getJSONObject("exact"),job.getJSONObject("binding"));}
    private static void noRemoteTool(McpLocalDiscoveryReviewTest.Fixture f,String id)throws Exception{assertFalse(Files.exists(f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(f.checkout).resolve("files/NEVER_CALL_REMOTE_TOOL")));assertFalse(Files.exists(f.android.getFilesDir().toPath().resolve("local-development/mcp-discovery-copies").resolve(id).resolve("NEVER_CALL_REMOTE_TOOL")));JSONObject actual=f.runtime.query(originalRef(f,id)).json();assertFalse(actual.optString("stderr").contains("OWN_METHOD:tools/call"));assertTrue(actual.optBoolean("processLaunched"));}
    private static JSONObject start(McpLocalDiscoveryReviewTest.Fixture f)throws Exception{McpLocalDiscovery.Confirmed approved=f.confirmed();RunControl original=new RunControl();f.tasks.beginOwnerMcpDiscoveryForOwner(approved,original);return McpLocalDiscoveryPipe.run(approved,f.tasks,original);}
    @Test public void actualPythonMcpInitializesOnceAndOnlyCompletesAfterOriginalProcessAndLeaseRelease()throws Exception{try(var f=new McpLocalDiscoveryReviewTest.Fixture("python3","server.py",python(McpStdioClient.VERSION,""))){JSONObject view=start(f);String id=view.getString("taskId");assertEquals(view.toString(),"completed",view.getString("status"));JSONObject receipt=view.getJSONObject("receipt"),process=receipt.getJSONObject("processReceipt");assertTrue(receipt.getBoolean("metadataAvailable"));assertTrue(receipt.getBoolean("processSettled"));assertTrue(receipt.getBoolean("outcomeSettled"));assertTrue(process.getBoolean("processExited"));assertTrue(process.getBoolean("processSessionAbsent"));assertTrue(process.getBoolean("processGroupAbsent"));assertTrue(process.getBoolean("resourcesReleased"));assertEquals(0,process.getInt("exitCode"));assertFalse(receipt.getBoolean("installationAuthorized"));assertFalse(receipt.getBoolean("modelInferenceStarted"));assertEquals(1,receipt.getJSONObject("metadata").getJSONArray("tools").length());assertFalse(view.toString().contains("--public-mode"));assertFalse(view.toString().contains("DO_NOT_INJECT"));assertEquals(0,f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(1,f.tasks.list().length());assertEquals(1,f.tasks.get(id,false).getJSONArray("operations").length());assertFalse(f.tasks.hasUnresolved(id));assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));noRemoteTool(f,id);JSONObject actual=f.runtime.query(originalRef(f,id)).json();assertEquals(1,actual.getString("stderr").split("OWN_METHOD:initialize\\n",-1).length-1);assertTrue(actual.getString("stderr").contains("OWN_METHOD:notifications/initialized"));assertTrue(actual.getString("stderr").contains("OWN_METHOD:tools/list"));assertFalse(actual.has("argv"));}}
    @Test public void actualNodeUsesTheSameOriginalProtocolAndNoPythonHttpOrPtySurrogate()throws Exception{String program="const readline=require('node:readline');const lines=readline.createInterface({input:process.stdin});lines.on('line',line=>{const q=JSON.parse(line);console.error('OWN_METHOD:'+q.method);let result;if(q.method==='initialize')result={protocolVersion:'2025-11-25',capabilities:{tools:{}},serverInfo:{name:'Native Node MCP',version:'1'}};else if(q.method==='tools/list')result={tools:[{name:'lookup',inputSchema:{type:'object'}}]};else return;process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:q.id,result})+'\\n');});";try(var f=new McpLocalDiscoveryReviewTest.Fixture("node","server.js",program)){JSONObject view=start(f);assertEquals(view.toString(),"completed",view.getString("status"));String id=view.getString("taskId");assertEquals("node",view.getJSONObject("scope").getString("executable"));assertEquals("pipes",f.runtime.query(originalRef(f,id)).json().getString("terminalMode"));assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));noRemoteTool(f,id);}}
    @Test public void actualUnsupportedNegotiationEndsWithoutInstallToolCallOrReplay()throws Exception{try(var f=new McpLocalDiscoveryReviewTest.Fixture("python3","server.py",python("2026-07-28",""))){JSONObject view=start(f);String id=view.getString("taskId");assertEquals(view.toString(),"failed",view.getString("status"));assertFalse(view.getJSONObject("receipt").getBoolean("metadataAvailable"));assertTrue(view.getJSONObject("receipt").getJSONObject("processReceipt").getBoolean("resourcesReleased"));assertEquals(0,f.plugins.snapshot().getJSONArray("plugins").length());noRemoteTool(f,id);assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));}}
    @Test public void actualNonProtocolStdoutPoisonsTheSessionAndCannotBecomeAUsableTool()throws Exception{try(var f=new McpLocalDiscoveryReviewTest.Fixture("python3","server.py",python(McpStdioClient.VERSION,"  print('not a protocol frame',flush=True)\n"))){JSONObject view=start(f);String id=view.getString("taskId");assertEquals(view.toString(),"failed",view.getString("status"));assertFalse(view.getJSONObject("receipt").getBoolean("metadataAvailable"));assertTrue(view.getJSONObject("receipt").getJSONObject("processReceipt").getBoolean("resourcesReleased"));assertEquals(0,f.plugins.snapshot().getJSONArray("plugins").length());noRemoteTool(f,id);}}
    @Test public void originalOwnerCancelStopsTheSameNativeJobWithoutReinitializingOrCallingTools()throws Exception{try(var f=new McpLocalDiscoveryReviewTest.Fixture("python3","server.py",python(McpStdioClient.VERSION,"  time.sleep(20)\n"))){McpLocalDiscovery.Confirmed approved=f.confirmed();RunControl original=new RunControl();f.tasks.beginOwnerMcpDiscoveryForOwner(approved,original);ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<JSONObject> pending=worker.submit(()->McpLocalDiscoveryPipe.run(approved,f.tasks,original));long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<until){JSONObject row=f.tasks.ownerMcpDiscoveryForOwner(approved.actionId());if(row.optJSONObject("nativeJob")!=null)try{if(f.runtime.query(originalRef(f,approved.actionId())).json().optString("stderr").contains("OWN_METHOD:tools/list"))break;}catch(IllegalArgumentException notYetPublished){/* Original SQL dispatch fence precedes the real Job receipt. */}Thread.sleep(20);}assertTrue(f.runtime.query(originalRef(f,approved.actionId())).json().getString("stderr").contains("OWN_METHOD:tools/list"));f.tasks.cancelOwnerMcpDiscoveryForOwner(approved.actionId());original.cancel();JSONObject view=pending.get(8,TimeUnit.SECONDS);assertEquals(view.toString(),"failed",view.getString("status"));assertTrue(view.getJSONObject("receipt").getJSONObject("processReceipt").getBoolean("resourcesReleased"));noRemoteTool(f,approved.actionId());assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));assertFalse(f.tasks.hasUnresolved(approved.actionId()));}finally{original.cancel();worker.shutdownNow();}}}
    @Test public void completedOriginalLedgerIsReadOnlyAndThePrivateApprovalCannotBeRecreatedAfterRun()throws Exception{try(var f=new McpLocalDiscoveryReviewTest.Fixture("python3","server.py",python(McpStdioClient.VERSION,""))){McpLocalDiscovery.Confirmed approved=f.confirmed();RunControl original=new RunControl();f.tasks.beginOwnerMcpDiscoveryForOwner(approved,original);JSONObject completed=McpLocalDiscoveryPipe.run(approved,f.tasks,original);String id=approved.actionId();assertEquals("completed",completed.getString("status"));String before=f.runtime.query(originalRef(f,id)).json().getString("stderr");JSONObject again=McpLocalDiscoveryPipe.publicView(f.tasks.ownerMcpDiscoveryForOwner(id));assertEquals("completed",again.getString("status"));assertFalse(again.has("nativeJob"));assertThrows(Exception.class,()->McpLocalDiscoveryPipe.run(approved,f.tasks,original));assertEquals(before,f.runtime.query(originalRef(f,id)).json().getString("stderr"));assertThrows(SecurityException.class,()->f.tasks.startAttempt(id,"capabilities",1));assertEquals(1,f.tasks.list().length());}}
    @Test public void missingCopiedDependencyFailsWithoutReadingOriginalNodeModulesOrInstallingAnything()throws Exception{String program="require('./node_modules/not-selected/module.js');";try(var f=new McpLocalDiscoveryReviewTest.Fixture("node","server.js",program)){Path original=f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(f.checkout).resolve("files"),module=original.resolve("node_modules/not-selected/module.js");Files.createDirectories(module.getParent());Files.write(module,"process.stderr.write('ORIGINAL_DEPENDENCY_MUST_NOT_RUN');".getBytes(java.nio.charset.StandardCharsets.UTF_8));JSONObject view=start(f);String id=view.getString("taskId");assertEquals(view.toString(),"failed",view.getString("status"));assertFalse(view.getJSONObject("receipt").getBoolean("metadataAvailable"));assertTrue(view.getJSONObject("receipt").getJSONObject("processReceipt").getBoolean("resourcesReleased"));assertFalse(Files.exists(f.android.getFilesDir().toPath().resolve("local-development/mcp-discovery-copies").resolve(id).resolve("node_modules")));assertFalse(f.runtime.query(originalRef(f,id)).json().optString("stderr").contains("ORIGINAL_DEPENDENCY_MUST_NOT_RUN"));assertEquals(0,f.plugins.snapshot().getJSONArray("plugins").length());}}

}
